<?php require 'common.php'; $mode=lab_mode(); $current=(int)($_GET['user']??101); if(!in_array($current,[101,102,103],true))$current=101; $id=(int)($_GET['id']??201); $st=$ket_noi->prepare('SELECT d.*,u.username FROM security_lab_documents d JOIN security_lab_users u ON u.id=d.owner_id WHERE d.id=?');$st->execute([$id]);$doc=$st->fetch();$allowed=$doc&&($mode==='vulnerable'||(int)$doc['owner_id']===$current||($mode==='fixed'&&$current===103)); if(!$allowed){http_response_code(403);audit('IDOR',$mode,'GET',$_SERVER['REQUEST_URI']??'',403,'forbidden','Server-side ownership/role check denied object access.');}else audit('IDOR',$mode,'GET',$_SERVER['REQUEST_URI']??'',200,'object-access','Vulnerable mode intentionally omits authorization.'); ?><!doctype html><html lang="vi"><head><meta charset="utf-8"><title>IDOR Lab</title></head><body style="font-family:Arial;max-width:950px;margin:30px auto"><h1>IDOR — Insecure Direct Object Reference</h1><p>Current lab user: <b><?=h($current)?></b> · Mode: <b><?=h($mode)?></b></p><form><label>User <select name="user"><option value="101" <?=$current===101?'selected':''?>>User A</option><option value="102" <?=$current===102?'selected':''?>>User B</option><option value="103" <?=$current===103?'selected':''?>>Admin</option></select></label><label> Object ID <input name="id" value="<?=h($id)?>"></label><select name="mode"><option value="vulnerable" <?=$mode==='vulnerable'?'selected':''?>>vulnerable</option><option value="fixed" <?=$mode==='fixed'?'selected':''?>>fixed</option></select><button>Request object</button></form><?php if($allowed):?><pre><?=h(print_r($doc,true))?></pre><?php else:?><h2 style="color:#b91c1c">403 Forbidden</h2><p>User không sở hữu object này.</p><?php endif;?><p>Fixed: authorization phải được kiểm tra ở server cho từng object; không tin ID do client cung cấp.</p><a href="index.php">← Lab menu</a></body></html>